 "Mission records, vehicles and the full development history are in the Missions archive, the Vehicle Hangar and the Development Timeline.": "任務紀錄、載具與完整的開發歷程，都收錄在任務檔案、載具機庫與開發時間軸中。",
 "All news": "所有消息",
 "The Aegis Landing Simulator's booster descending on its engines with its landing legs deployed": "Aegis 著陸模擬器的助推器以引擎減速下降，著陸腳已展開",
 "The WSA Engineering Sandbox is a small aerospace laboratory in 3D.": "WSA 工程沙盒是一座小型的 3D 航太實驗室。",
 "Its seven experiments cover an engine test stand with a side-by-side engine comparison, a thrust-to-weight and lift-off lab, multi-stage rockets, orbital burns, Hohmann transfers, a booster landing lab and a free-play rocket sandbox.": "七個實驗包括：可並排比較引擎的引擎測試台、推重比與升空實驗室、多級火箭、軌道點火、霍曼轉移、助推器著陸實驗室，以及自由遊玩的火箭沙盒。",
 "Basic mode explains each setting in plain words; Pro mode exposes the full set of parameters, from specific impulse to the integrator's time step.": "基礎模式以淺白的文字說明每項設定；專業模式則開放完整的參數，從比衝到積分器的時間步長都能調整。",
 "Every experiment has live telemetry, graphs, an event log, replays and a debrief.": "每個實驗都有即時遙測、圖表、事件紀錄、重播與任務講評。",
 "The Aegis Landing Simulator puts you at the controls of a reusable booster in its final descent.": "Aegis 著陸模擬器讓你操控一具處於最後下降階段的可重複使用助推器。",
 "Manage the throttle, propellant and the booster's attitude to touch down upright on the pad, at Easy, Normal or Hard difficulty.": "控制節流閥、推進劑與助推器的姿態，讓它直立降落在著陸台上，難度分為簡單、普通與困難。",
 "Each attempt ends with an honest score, an award and a certificate you can download or share.": "每次嘗試結束後都會得到誠實的分數、一個獎項，以及可以下載或分享的證書。",
 "The landing game is inspired by WSA's reusable booster programme; it is not a recreation of AutoLand's real pad landing.": "這款著陸遊戲的靈感來自 WSA 的可重複使用助推器計畫，並不是 AutoLand 真實著陸台著陸的重現。",
