 "AutoLand V2.2 kept missing its target by more than 1.6 km.": "AutoLand V2.2 一直偏離目標超過 1.6 km。",
 "A miss that large and that consistent made the team suspicious, and they realised the guidance was missing Kerbin's rotation.": "偏差這麼大又這麼一致，讓團隊起了疑心，他們發現導引系統沒有考慮 Kerbin 的自轉。",
 "With the rotation accounted for, V2.2 came down within about 500 m of its target.": "把自轉納入計算後，V2.2 的落點距離目標約 500 m 以內。",
 "V2.3 closed the remaining few hundred metres.": "V2.3 則消除了剩下的幾百公尺。",
