 "The precision landing in the video put the booster down on the pad's marked centre, where it stayed upright.": "影片中的精準著陸讓助推器降落在著陸台標示的中心，並保持直立。",
 "The booster in the video is the new Aegis Mk1.7 design.": "影片中的助推器是新的 Aegis Mk1.7 設計。",
