 "About WSA | Woody Space Agency": "關於 WSA | Woody Space Agency",
 "About Woody Space Agency": "關於 Woody Space Agency",
 "A small, independent aerospace organization pursuing ambitious spaceflight through incremental engineering and reusable systems.": "一個小型的獨立航太組織，透過循序漸進的工程與可重複使用的系統，追求遠大的太空飛行目標。",
 "Wonders Seek Above.": "向上探尋奇蹟。",
 "Aiming for the Stars.": "志在星辰。",
 "WSA's two mottos.": "WSA 的兩句座右銘。",
 "The first shares the agency's initials; both are written on the flags WSA crews plant on other worlds.": "第一句與機構名稱的英文縮寫相同；兩句都寫在 WSA 機組人員插在其他星球上的旗幟上。",
 "Engineering Philosophy": "工程理念",
 "WSA's core principle is to develop engineering solutions step-by-step, learning from each test and iteration rather than immediately reaching for third-party automation.": "WSA 的核心原則是一步一步開發工程解決方案，從每次測試與迭代中學習，而不是立刻依賴第三方的自動化工具。",
 "This approach demands patience, rigorous documentation, honest failure analysis, and continuous improvement.": "這種做法需要耐心、嚴謹的紀錄、誠實的失敗分析，以及持續的改進。",
 "Incremental Development": "循序漸進的開發",
 "Systems are built through successive refinement.": "系統是經由不斷改良建立起來的。",
 "Each test flight, mission, or experiment teaches something about the vehicle, the control system, or the mission profile.": "每一次試飛、任務或實驗，都讓我們更了解載具、控制系統或任務規劃。",
 "Failures are documented as learning opportunities, not setbacks.": "失敗被記錄為學習的機會，而不是挫折。",
 "Homemade Guidance & Control": "自製導引與控制",
 "Rather than delegating all autonomous tasks to external mods, WSA develops custom flight controllers and guidance systems (like AutoLand) to understand how spacecraft actually behave and respond to control inputs.": "WSA 不把所有自主任務都交給外部模組，而是自行開發飛行控制器與導引系統（例如 AutoLand），以了解太空載具實際上如何運作、如何回應控制輸入。",
 "Reusable-First Design": "以重複使用為優先的設計",
 "Boosters are designed for recovery, refurbishment, and reuse.": "助推器的設計以回收、整修與重複使用為目標。",
 "This drives engineering decisions about structure, landing systems, and operational procedures that would not exist in expendable designs.": "這影響了結構、著陸系統與作業程序的工程決策，而這些在一次性設計中都不會存在。",
 "Reliable Operations": "可靠的運作",
 "WSA prioritizes systems that can repeat their performance consistently.": "WSA 優先發展能穩定重現性能的系統。",
 "A vehicle that lands safely once proves a concept; a vehicle that lands safely 47+ times proves a capability.": "一具載具安全著陸一次，證明的是概念；一具載具安全著陸 47 次以上，證明的是能力。",
 "Mission-Focused": "以任務為核心",
 "Development is driven by real mission objectives: reaching the Mun, assembling an orbital station, recovering boosters, supporting crew transport.": "開發由真實的任務目標驅動：抵達 Mun、組裝軌道太空站、回收助推器、支援機組運輸。",
 "Technology is built to serve these goals.": "技術是為這些目標而打造的。",
 "Documented Learning": "有紀錄的學習",
 "Flight records, engineering decisions, problems, and solutions are documented.": "飛行紀錄、工程決策、問題與解決方案都會被記錄下來。",
 "This archive allows WSA to review progress, avoid repeating mistakes, and make informed decisions about future programs.": "這份檔案讓 WSA 能回顧進展、避免重蹈覆轍，並為未來的計畫做出明智的決定。",
 "Core Interests": "核心領域",
 "WSA's engineering work focuses on these interconnected technical areas:": "WSA 的工程工作專注於以下相互關聯的技術領域：",
 "Reusable Booster Development & Recovery": "可重複使用助推器的開發與回收",
 "Designing boosters that survive descent, landing, and recovery.": "設計能撐過下降、著陸與回收的助推器。",
 "This includes structural design for reuse, thermal management, landing-gear systems, and operational procedures for refurbishment.": "內容包括可重複使用的結構設計、熱管理、起落裝置系統，以及整修的作業程序。",
 "Autonomous Descent, Guidance & Landing Control": "自主下降、導引與著陸控制",
 "Building guidance systems that predict trajectories, manage throttle, and guide vehicles to precision landings.": "打造能預測軌跡、控制節流閥，並把載具導引至精準著陸的導引系統。",
 "AutoLand represents the flagship effort in this area: a custom kOS system whose V2.3 has landed an Aegis booster on its target pad, and which is now being made repeatable and dependable.": "AutoLand 是這個領域的旗艦成果：一套自訂的 kOS 系統，其 V2.3 已讓一具 Aegis 助推器降落在目標著陸台上，目前正努力讓它可重複且可靠。",
 "Orbital Station Construction & Logistics": "軌道太空站的建造與後勤",
