 "Programs like Swift-1X and SSTO development explore aerodynamic and orbital-transition challenges.": "Swift-1X 與 SSTO 開發等計畫，探索空氣動力學以及從大氣層過渡到軌道的挑戰。",
 "Mun, Minmus, Duna & Planetary Exploration": "Mun、Minmus、Duna 與行星探索",
