 "Documented route (none recorded yet)": "有紀錄的航線（目前尚無）",
 "Planned or intended route that was not flown": "規劃或原定但未飛行的航線",
 "Recorded event; select it to jump there": "已記錄的事件；選擇它即可跳到該處",
 "Mission position during the replay": "重播時的任務位置",
 "Bodies are not to scale and are shown in an illustrative layout.": "天體並未按比例繪製，採用示意配置。",
 "Drag to rotate.": "拖曳可旋轉。",
