 "Custom value": "自訂數值",
 "Enter a target Δv": "輸入目標 Δv",
 "Ideal figure: no gravity, drag or steering losses.": "理想數值：沒有重力、阻力或轉向損失。",
 "WSA's current installation: the stock Kerbol system plus the Outer Planets Mod (Sarnus, Urlum, Neidon, Plock and their moons; Eeloo becomes a moon of Sarnus).": "WSA 目前的安裝：原版 Kerbol 星系加上 Outer Planets Mod（Sarnus、Urlum、Neidon、Plock 及其衛星；Eeloo 成為 Sarnus 的衛星）。",
 "Read from the installation's Kopernicus logs.": "讀取自安裝中的 Kopernicus 記錄檔。",
 "Six games: design a space station, fly a spacecraft in to dock with one, bring a spaceplane home to the runway, plan an orbital rendezvous with KGOSS, experiment with rocket engineering in the 3D Engineering Sandbox, or land an Aegis booster on its recovery pad.": "六款遊戲：設計一座太空站、駕駛太空船與太空站對接、讓太空飛機返航降落在跑道上、規劃與 KGOSS 的軌道交會、在 3D 工程沙盒中實驗火箭工程，或讓 Aegis 助推器降落在回收著陸台上。",
 "Station Builder": "太空站建造器",
 "Assemble an orbital station from 17 modules: nodes, laboratories, habitats, trusses, solar arrays and more.": "用 17 種模組組裝一座軌道太空站：節點艙、實驗室、居住艙、桁架、太陽能板等等。",
 "Snap them together, then save a picture of your build to download or share.": "把它們拼接起來，再存下你的作品圖片來下載或分享。",
 "Mouse or touch": "滑鼠或觸控",
 "Play Station Builder": "遊玩太空站建造器",
 "Docking Simulator": "對接模擬器",
 "Pilot a spacecraft in first person and dock it with an orbital station.": "以第一人稱駕駛太空船，與軌道太空站對接。",
 "Line up with the port, watch your closing speed and make a gentle contact.": "對準對接埠、注意接近速度，輕柔地接觸。",
 "Best with a keyboard": "建議使用鍵盤",
 "touch controls on phones": "手機可用觸控操作",
