 "Fly a small spaceplane down to the spaceport runway: line up, descend, flare and touch down gently.": "駕駛一架小型太空飛機降落到太空港跑道：對準、下降、拉平並輕柔觸地。",
 "Get a grade, earn awards, and save or share your landing card.": "獲得評等、贏得獎項，並儲存或分享你的著陸卡。",
