 "The Docking Simulator is made for a keyboard and a larger screen, so it plays best on a desktop or laptop.": "對接模擬器是為鍵盤與較大的螢幕設計的，因此在桌上型或筆記型電腦上玩效果最好。",
 "You can still fly it here with on-screen controls: pick a joystick or big buttons above the view.": "你仍然可以在這裡用螢幕上的控制項駕駛：在畫面上方選擇搖桿或大按鈕。",
