 "Cancel unwanted drift.": "消除不需要的漂移。",
 "Line up: put the centre marker on the axis crosshairs and level the roll.": "對準：把中心標記放在軸線十字準線上，並把滾轉擺正。",
 "Translate until the port reticle sits on the crosshairs.": "平移直到對接埠準星落在十字準線上。",
 "Close slowly, staying inside the corridor gates.": "緩慢接近，保持在通道門框內。",
 "Keep the prograde marker on the port and slow down as you get near.": "讓順行標記保持在對接埠上，接近時放慢速度。",
