 "Line up with the centreline, follow the glide path down, flare, touch down gently on the main wheels and brake to a stop on the runway.": "對準中心線，沿著下滑道下降，拉平，以主輪輕柔觸地，然後煞車停在跑道上。",
 "Scenario": "情境",
 "Training": "訓練",
 "Lined up, slower and closer, gear already down.": "已對準、速度較慢且距離較近，起落架已放下。",
 "Standard": "標準",
 "Off the centreline and a little fast.": "偏離中心線，速度稍快。",
 "Lower the gear yourself.": "需要自己放下起落架。",
 "Advanced": "進階",
 "Far out, high, fast and well off the centreline, with a crosswind.": "距離遠、高度高、速度快且大幅偏離中心線，還有側風。",
 "How to land": "如何著陸",
 "Turn toward the runway and put the centreline under the nose.": "轉向跑道，讓中心線位於機頭正下方。",
 "Lower the landing gear.": "放下起落架。",
 "Descend along the glide path: the PAPI lights left of the runway show two white and two red when you're on it.": "沿著下滑道下降：當你在下滑道上時，跑道左側的 PAPI 燈會顯示兩白兩紅。",
 "Over the runway, throttle to idle and raise the nose gently to flare.": "到達跑道上空時，把節流閥收到怠速，並輕輕抬起機頭拉平。",
 "Touch down on the main wheels, wings level, then brake to a stop.": "以主輪觸地、機翼保持水平，然後煞車停下。",
 "rudder": "方向舵",
 "Throttle": "節流閥",
 "Choose Mouse above the view.": "在畫面上方選擇「滑鼠」。",
 "The pointer works like a control stick: above the centre lowers the nose, below raises it, left and right roll.": "游標的作用就像操縱桿：在中心上方壓低機頭，在下方抬高機頭，左右為滾轉。",
 "The wheel sets the throttle.": "滾輪用來設定節流閥。",
 "Stick: up lowers the nose, left and right roll.": "搖桿：向上壓低機頭，左右為滾轉。",
 "THR slider: throttle.": "節流滑桿：節流閥。",
 "GEAR, hold BRAKE, ◀ ▶ rudder, CAM: camera.": "起落架、按住煞車、◀ ▶ 方向舵、鏡頭：攝影機。",
 "Choose Tilt above the view to fly by tilting the device: tip it away to lower the nose, left or right to roll.": "在畫面上方選擇「傾斜」，即可透過傾斜裝置來飛行：向前傾壓低機頭，向左或向右傾滾轉。",
 "Calibrate sets how you hold it as level.": "「校正」會把你目前的握持方式設為水平。",
 "Flight Assist": "飛行輔助",
 "holds the attitude when you let go, limits bank and pitch, prevents stalls and shows approach gates.": "放開時保持姿態、限制坡度與俯仰、防止失速，並顯示進場門框。",
