 "Return to Games": "返回遊戲",
 "How rendezvous works": "交會的原理",
 "Close is not the same as matched": "靠近不等於速度相符",
 "You can fly right past it while only a few hundred metres away if your velocity is different.": "如果你的速度不同，即使只相距幾百公尺，也可能直接從它旁邊飛過。",
 "and": "並且",
 "relative velocity": "相對速度",
 "The lessons": "課程",
 "Your craft is blue.": "你的載具是藍色的。",
 "Both orbit anticlockwise, and lower orbits go round faster.": "兩者都以逆時針方向繞行，軌道越低繞得越快。",
 "Read the map.": "閱讀地圖。",
 "Prograde and retrograde.": "順行與逆行。",
 "Burn.": "點火。",
 "Watch the orbit change.": "觀察軌道的變化。",
 "The closest-approach marker shows how near you'll pass.": "最接近點標記會顯示你將從多近的距離通過。",
 "Plan a transfer.": "規劃轉移。",
 "Match its motion.": "匹配它的運動。",
 "Faster than the safe speed for your distance is unsafe.": "以你的距離而言，超過安全速度就是不安全的。",
 "Reduce relative velocity.": "降低相對速度。",
 "Fly up the corridor behind it, nose on the docking axis, and touch the port gently.": "從它後方沿著通道飛上去，機頭對準對接軸線，輕柔地接觸對接埠。",
 "Final approach.": "最終接近。",
 "Turn": "轉向",
 "With Flight Assist on, the craft stops turning when you let go; with it off, it keeps spinning until you counter it.": "開啟飛行輔助時，放開後載具會停止轉動；關閉時，它會一直旋轉直到你反向修正。",
 "Main engine": "主引擎",
 "Fine control": "微調控制",
 "Time and view": "時間與畫面",
 "⟲ ⟳ turn, hold BURN for the main engine, THR − + throttle.": "⟲ ⟳ 轉向，按住「點火」使用主引擎，節流 − + 調整節流閥。",
 "The four arrows translate.": "四個箭頭用來平移。",
 "PRO, RETRO, TGT, MATCH and DOCK are the Flight Assist holds. « » change time warp.": "順行、逆行、目標、匹配與對接是飛行輔助的鎖定方向。« » 調整時間加速。",
 "Optional: switch on Tilt to turn by tipping the device left and right.": "選用：開啟「傾斜」即可透過左右傾斜裝置來轉向。",
 "The game asks the browser for motion data only then, and only to steer.": "遊戲只有在那時才會向瀏覽器要求動作感測資料，而且只用於轉向。",
 "Calibrate sets how you're holding it as level.": "「校正」會把你目前的握持方式設為水平。",
 "The buttons always work too.": "按鈕也隨時可用。",
 "About the simulation": "關於模擬",
