 "Fly up the approach corridor and dock gently.": "沿著接近通道飛上去，輕柔地對接。",
 "Start a little below KGOSS and catch it up: one burn to rise to its orbit, then match its motion and dock.": "從 KGOSS 稍低的位置出發並追上它：一次點火升到它的軌道，然後匹配它的運動並對接。",
