 "Engine Test Stand": "引擎測試台",
 "Fire a rocket engine on a test stand.": "在測試台上點燃火箭引擎。",
 "Change its power, efficiency and fuel, and compare two engines side by side.": "改變它的功率、效率與燃料，並並排比較兩具引擎。",
 "Total impulse depends only on the fuel and the efficiency.": "總衝量只取決於燃料與效率。",
 "You'll learn:": "你將學到：",
 "Thrust-to-Weight and Lift-Off Lab": "推重比與升空實驗室",
 "A rocket on the pad: will it lift off, sit still or leap away?": "發射台上的一枚火箭：它會升空、原地不動，還是猛然衝出去？",
 "Change its mass, engines and gravity and find out.": "改變它的質量、引擎與重力，親自找出答案。",
 "As fuel burns, the rocket gets lighter and its TWR rises.": "隨著燃料燃燒，火箭變輕，推重比也隨之上升。",
 "Staging Laboratory": "分級實驗室",
 "Intermediate": "中級",
 "Build a rocket of up to four stages, fire it and drop each empty stage.": "打造一枚最多四節的火箭，點火升空並拋棄每一節用完的部分。",
 "See how shedding dead weight adds speed.": "看看甩掉無用的重量如何增加速度。",
 "Dropping empty tanks and engines makes the remaining rocket lighter, so the next stage achieves more.": "拋棄空的燃料槽與引擎會讓剩下的火箭變輕，因此下一節能發揮更多。",
 "Orbital Mechanics Laboratory": "軌道力學實驗室",
 "A spacecraft in orbit.": "一艘在軌道上的太空船。",
 "Fire burns forwards, backwards, inwards or outwards and watch the orbit change shape.": "向前、向後、向內或向外點火，觀察軌道形狀的變化。",
 "Hohmann Transfer Laboratory": "霍曼轉移實驗室",
 "Move between two circular orbits with two burns.": "以兩次點火在兩條圓軌道之間移動。",
 "Fire them by hand, or catch a satellite waiting in the target orbit.": "手動點火，或去追上在目標軌道上等待的衛星。",
 "Autonomous Landing Laboratory": "自主著陸實驗室",
 "Bring a reusable booster down onto its pad.": "讓可重複使用的助推器降落到著陸台上。",
 "Let the guidance fly it, tune it, or take the controls yourself.": "交給導引系統飛、調整它，或親自操控。",
 "Lean the thrust to move sideways; burn too late and there isn't enough thrust to stop.": "傾斜推力方向就能橫向移動；點火太晚，推力就不足以停下來。",
 "Free-Play Engineering Sandbox": "自由遊玩工程沙盒",
 "Open": "開放",
 "Build a rocket of up to three stages, choose where it starts and how it steers, then fly it: to orbit, to space or straight back down.": "打造一枚最多三節的火箭，選擇它的出發地點與轉向方式，然後駕駛它：上軌道、上太空，或直接落回地面。",
 "Run the engine for its whole planned burn without the tank running dry.": "讓引擎完成整段計畫的點火，而不讓燃料槽用完。",
 "Thrust decides how hard an engine pushes; specific impulse decides how long the fuel lasts.": "推力決定引擎推得多用力；比衝決定燃料能撐多久。",
