 "Ideal Hohmann transfer between circular, coplanar orbits round one point-mass body; no drag, no other bodies.": "繞單一質點天體、在共平面圓軌道之間的理想霍曼轉移；沒有阻力，沒有其他天體。",
 "Burns are impulsive (instantaneous).": "點火是瞬間的。",
