 "Spacecraft firing its engine above the ocean": "在海面上空點燃引擎的太空船",
 "Capsule floating in the ocean after splashdown": "濺落後漂浮在海面上的太空艙",
 "FSX-3 surrounded by heating effects at Mach 5": "在 5 馬赫時被氣動加熱效果包圍的 FSX-3",
 "At Mach 5": "5 馬赫",
